 headers={'date': 'Mon, 26 Oct 2026 17:25:53 GMT', 'server': 'uvicorn', 'content-length': '4343', 'content-type': 'application/json', 'vary': 'Origin'} 
 body={"version":"1.0","max_points":40,"questions":[{"id":"q1_idade","text":"Qual a sua idade?","help_text":"Quanto maior o tempo até a aposentadoria, maior a capacidade de absorver oscilações.","scores":true,"options":[{"value":"ate_30","label":"Até 30 anos"},{"value":"31_45","label":"Entre 31 e 45 anos"},{"value":"46_60","label":"Entre 46 e 60 anos"},{"value":"mais_60","label":"Mais de 60 anos"}]},{"id":"q2_percentual_renda","text":"Quanto da sua renda mensal você consegue investir?","help_text":null,"scores":true,"options":[{"value":"menos_5","label":"Menos de 5%"},{"value":"5_15","label":"Entre 5% e 15%"},{"value":"15_30","label":"Entre 15% e 30%"},{"value":"mais_30","label":"Mais de 30%"}]},{"id":"q3_reserva","text":"Você tem reserva de emergência?","help_text":"Reserva de emergência é pré-requisito para investir em renda variável.","scores":true,"options":[{"value":"nao","label":"Não tenho"},{"value":"menos_3m","label":"Sim, menos de 3 meses de custo de vida"},{"value":"3_6m","label":"Sim, de 3 a 6 meses"},{"value":"mais_6m","label":"Sim, mais de 6 meses"}]},{"id":"q4_horizonte","text":"Por quanto tempo pretende deixar o dinheiro investido?","help_text":null,"scores":true,"options":[{"value":"menos_1a","label":"Menos de 1 ano"},{"value":"1_3a","label":"De 1 a 3 anos"},{"value":"3_10a","label":"De 3 a 10 anos"},{"value":"mais_10a","label":"Mais de 10 anos"}]},{"id":"q5_reacao_queda","text":"Sua carteira cai 20% em um mês. O que você faz?","help_text":"Mede tolerância emocional a risco — o fator que mais destrói retorno na prática.","scores":true,"options":[{"value":"vendo_tudo","label":"Vendo tudo para não perder mais"},{"value":"vendo_parte","label":"Vendo parte para reduzir o risco"},{"value":"mantenho","label":"Mantenho e espero a recuperação"},{"value":"compro_mais","label":"Aproveito e compro mais"}]},{"id":"q6_experiencia","text":"Qual sua experiência com investimentos?","help_text":null,"scores":true,"options":[{"value":"nenhuma","label":"Nenhuma"},{"value":"renda_fixa","label":"Só renda fixa (poupança, CDB, Tesouro)"},{"value":"fundos_etf","label":"Fundos de investimento ou ETFs"},{"value":"acoes","label":"Já invisto em ações"},{"value":"derivativos","label":"Ações e derivativos (opções, futuros)"}]},{"id":"q7_conhecimento","text":"Como você avalia seu conhecimento sobre o mercado financeiro?","help_text":null,"scores":true,"options":[{"value":"nenhum","label":"Nenhum"},{"value":"basico","label":"Básico"},{"value":"intermediario","label":"Intermediário"},{"value":"avancado","label":"Avançado"}]},{"id":"q8_fatia_patrimonio","text":"Que fatia do seu patrimônio ficará investida em ações?","help_text":null,"scores":true,"options":[{"value":"menos_10","label":"Menos de 10%"},{"value":"10_30","label":"Entre 10% e 30%"},{"value":"30_60","label":"Entre 30% e 60%"},{"value":"mais_60","label":"Mais de 60%"}]},{"id":"q9_preferencia","text":"O que você prefere?","help_text":null,"scores":true,"options":[{"value":"preservar","label":"Preservar o valor, mesmo rendendo pouco"},{"value":"equilibrio","label":"Equilíbrio entre segurança e retorno"},{"value":"maximo_retorno","label":"Máximo retorno possível, aceito perdas no caminho"}]},{"id":"q10_dependentes","text":"Quantas pessoas dependem financeiramente da sua renda?","help_text":null,"scores":true,"options":[{"value":"varias","label":"Várias"},{"value":"uma","label":"Uma"},{"value":"nenhuma","label":"Nenhuma"}]},{"id":"q11_estabilidade_renda","text":"Sua renda é estável?","help_text":null,"scores":true,"options":[{"value":"instavel","label":"Instável / autônomo sem previsibilidade"},{"value":"media","label":"Média — varia de mês a mês"},{"value":"estavel","label":"Estável"},{"value":"muito_estavel","label":"Muito estável, com outras fontes de renda"}]},{"id":"q12_objetivo","text":"Qual é o seu objetivo principal ao investir?","help_text":"Não pontua risco: define o objetivo, que escolhe o vetor de pesos do motor de score.","scores":false,"options":[{"value":"renda","label":"Gerar renda passiva / me aposentar com dividendos"},{"value":"crescimento","label":"Fazer o patrimônio crescer o máximo possível"},{"value":"equilibrio","label":"Crescer com equilíbrio entre risco e retorno"},{"value":"preservacao","label":"Preservar o que já tenho, com segurança"}]}]}

